contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Take a dummy uint parameter to satisfy the requirement of having inputs.
    function run(uint dummy) public payable {
        require(true);

        // Observe state before the call
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // Call withdrawAll as owner (this contract). Must be a top-level statement.
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after state
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: If withdrawAll returns (does not revert), then C.balance == 0 and depositsCount did not decrease.
        assert(reverted || (afterBalance == 0 && afterDeposits >= beforeDeposits));
    }

    receive() external payable { }
}

